package com.crm.customer;
import com.crm.customer.client.AssignedEmployeeDirectory;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.web.server.ResponseStatusException;import org.junit.jupiter.api.Test;import java.util.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class AssignedEmployeeDirectoryTest {AssignedEmployeeDirectory directory=spy(new AssignedEmployeeDirectory(mock(DiscoveryClient.class)));ObjectMapper json=new ObjectMapper();
 @Test void uidAndEmployeeMustBeCanonicalTextFromAssociation()throws Exception{for(String value:List.of("null","[]","{\"userId\":\"43\",\"employeeId\":\"101\"}","{\"userId\":42,\"employeeId\":101}","{\"userId\":\"42\",\"employeeId\":\"01\"}","{\"userId\":\"42\",\"employeeId\":\"9223372036854775808\"}")){doReturn(json.readTree(value)).when(directory).read(any());assertEquals(502,assertThrows(ResponseStatusException.class,()->directory.own("Bearer synthetic",42)).getStatusCode().value());}doReturn(json.readTree("{\"userId\":\"42\",\"employeeId\":\"101\"}")).when(directory).read(any());assertEquals(101L,directory.own("Bearer synthetic",42));}
 @Test void missingBearerIsRejectedBeforeDiscovery(){assertEquals(401,assertThrows(ResponseStatusException.class,()->directory.own(null,42)).getStatusCode().value());verify(directory,never()).read(any());}
 @Test void unavailableDiscoveryFailsClosed(){var discovery=mock(DiscoveryClient.class);when(discovery.getInstances("hr-service")).thenReturn(List.of());var client=new AssignedEmployeeDirectory(discovery);assertEquals(503,assertThrows(ResponseStatusException.class,()->client.own("Bearer synthetic",42)).getStatusCode().value());}
 @Test void remoteRefusalsAreNotReplacedByFallbackIdentity(){for(int status:List.of(401,403,404,502,503)){doThrow(new ResponseStatusException(org.springframework.http.HttpStatus.valueOf(status))).when(directory).read(any());assertEquals(status,assertThrows(ResponseStatusException.class,()->directory.own("Bearer synthetic",42)).getStatusCode().value());}}
}
